// Message names, as the spec gives them.
const (
	// Something happened to an item.
	// Payload: Event.
	// Application headers: TraceHeaders.
	// Content type: application/cloudevents+json.
	MessageEvent = "event"
	// Payload: HeartbeatPayload.
	// Content type: application/json.
	//
	// Deprecated: the spec marks this message as deprecated.
	MessageHeartbeat = "heartbeat"
	// Adds bindings the message does not set, without replacing its own.
	// Payload: Command.
	// Content type: application/json.
	MessageCommand = "command"
	// Payload: CommandResult.
	// Content type: application/json.
	MessageCommandResult = "commandResult"
	// Payload: json.RawMessage.
	// Content type: application/avro.
	// The payload schema format application/vnd.apache.avro+json;version=1.9.0 is not JSON Schema, so the payload is raw JSON.
	MessageAvroReading = "avroReading"
	// Payload: Ping.
	// Content type: application/json.
	MessageExternalPing = "externalPing"
	// Payload: TelemetryInlinePayloadPayload.
	// Content type: application/json.
	MessageTelemetryInlinePayload = "telemetry_inlinePayload"
	// Payload: Tree.
	// Content type: application/json.
	MessageTreeMessage = "TreeMessage"
)

// MessageCommandCorrelationIDLocation is where a command message carries its
// correlation ID, as an AsyncAPI runtime expression.
const MessageCommandCorrelationIDLocation = "$message.payload#/commandId"

// MessageCommandResultCorrelationIDLocation is where a commandResult message carries its
// correlation ID, as an AsyncAPI runtime expression.
const MessageCommandResultCorrelationIDLocation = "$message.payload#/commandId"

// ReceivedMessage is a decoded incoming message. Payload holds the payload
// type of the message Name names.
type ReceivedMessage struct {
	Name    string
	Payload any
}

var receivedMessages = []asyncapirt.Candidate{
	{
		Name: MessageCommandResult,
		Decode: func(data []byte) (any, error) {
			var payload CommandResult
			if err := asyncapirt.UnmarshalStrict(data, &payload); err != nil {
				return nil, err
			}

			return payload, nil
		},
	},
	{
		Name: MessageEvent,
		Decode: func(data []byte) (any, error) {
			var payload Event
			if err := asyncapirt.UnmarshalStrict(data, &payload); err != nil {
				return nil, err
			}

			return payload, nil
		},
	},
	{
		Name: MessageHeartbeat,
		Matchers: []asyncapirt.Matcher{
			{Pointer: "/beat", Value: "true"},
		},
		Decode: func(data []byte) (any, error) {
			var payload HeartbeatPayload
			if err := asyncapirt.UnmarshalStrict(data, &payload); err != nil {
				return nil, err
			}

			return payload, nil
		},
	},
	{
		Name:     MessageAvroReading,
		Fallback: true,
		Decode: func(data []byte) (any, error) {
			var payload json.RawMessage
			if err := asyncapirt.UnmarshalStrict(data, &payload); err != nil {
				return nil, err
			}

			return payload, nil
		},
	},
	{
		Name: MessageExternalPing,
		Matchers: []asyncapirt.Matcher{
			{Pointer: "/ping", Value: "\"external\""},
		},
		Decode: func(data []byte) (any, error) {
			var payload Ping
			if err := asyncapirt.UnmarshalStrict(data, &payload); err != nil {
				return nil, err
			}

			return payload, nil
		},
	},
	{
		Name: MessageTelemetryInlinePayload,
		Decode: func(data []byte) (any, error) {
			var payload TelemetryInlinePayloadPayload
			if err := asyncapirt.UnmarshalStrict(data, &payload); err != nil {
				return nil, err
			}

			return payload, nil
		},
	},
}

// DecodeReceivedMessage works out which incoming message data is and decodes
// it. It fails with asyncapirt.ErrUnknownMessage when nothing matches and
// asyncapirt.ErrAmbiguousMessage when several messages match.
func DecodeReceivedMessage(data []byte) (ReceivedMessage, error) {
	name, payload, err := asyncapirt.DecodeMessage(data, receivedMessages)
	if err != nil {
		return ReceivedMessage{}, ctxerrors.Wrap(err, "decode received message")
	}

	return ReceivedMessage{Name: name, Payload: payload}, nil
}

// Handler receives incoming messages. Embed UnimplementedHandler to implement
// only the methods you need.
type Handler interface {
	// Payload: CommandResult.
	// Content type: application/json.
	HandleCommandResult(ctx context.Context, payload CommandResult) error
	// Something happened to an item.
	// Payload: Event.
	// Application headers: TraceHeaders.
	// Content type: application/cloudevents+json.
	HandleEvent(ctx context.Context, payload Event) error
	// Payload: HeartbeatPayload.
	// Content type: application/json.
	//
	// Deprecated: the spec marks this message as deprecated.
	HandleHeartbeat(ctx context.Context, payload HeartbeatPayload) error
	// Payload: json.RawMessage.
	// Content type: application/avro.
	// The payload schema format application/vnd.apache.avro+json;version=1.9.0 is not JSON Schema, so the payload is raw JSON.
	HandleAvroReading(ctx context.Context, payload json.RawMessage) error
	// Payload: Ping.
	// Content type: application/json.
	HandleExternalPing(ctx context.Context, payload Ping) error
	// Payload: TelemetryInlinePayloadPayload.
	// Content type: application/json.
	HandleTelemetryInlinePayload(ctx context.Context, payload TelemetryInlinePayloadPayload) error
	// HandleUnknownMessage gets every message that matched nothing, with the
	// reason. Returning an error stops Client.Run.
	HandleUnknownMessage(ctx context.Context, data []byte, err error) error
}

// UnimplementedHandler ignores every message. Its HandleUnknownMessage logs a
// warning and keeps the receive loop running.
type UnimplementedHandler struct{}

// HandleCommandResult ignores the message.
func (UnimplementedHandler) HandleCommandResult(context.Context, CommandResult) error {
	return nil
}

// HandleEvent ignores the message.
func (UnimplementedHandler) HandleEvent(context.Context, Event) error {
	return nil
}

// HandleHeartbeat ignores the message.
func (UnimplementedHandler) HandleHeartbeat(context.Context, HeartbeatPayload) error {
	return nil
}

// HandleAvroReading ignores the message.
func (UnimplementedHandler) HandleAvroReading(context.Context, json.RawMessage) error {
	return nil
}

// HandleExternalPing ignores the message.
func (UnimplementedHandler) HandleExternalPing(context.Context, Ping) error {
	return nil
}

// HandleTelemetryInlinePayload ignores the message.
func (UnimplementedHandler) HandleTelemetryInlinePayload(context.Context, TelemetryInlinePayloadPayload) error {
	return nil
}

// HandleUnknownMessage logs the message size and the reason, then continues.
func (UnimplementedHandler) HandleUnknownMessage(ctx context.Context, data []byte, err error) error {
	ctxscope.GetLogger(ctx).Warn(
		"ignoring incoming message",
		"err", err,
		"size_bytes", len(data),
		"reason", "no_matching_message",
	)

	return nil
}

// Dispatch passes message to the handler method for its name.
func Dispatch(ctx context.Context, handler Handler, message ReceivedMessage) error {
	switch message.Name {
	case MessageCommandResult:
		payload, ok := message.Payload.(CommandResult)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandleCommandResult(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	case MessageEvent:
		payload, ok := message.Payload.(Event)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandleEvent(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	case MessageHeartbeat:
		payload, ok := message.Payload.(HeartbeatPayload)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandleHeartbeat(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	case MessageAvroReading:
		payload, ok := message.Payload.(json.RawMessage)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandleAvroReading(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	case MessageExternalPing:
		payload, ok := message.Payload.(Ping)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandleExternalPing(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	case MessageTelemetryInlinePayload:
		payload, ok := message.Payload.(TelemetryInlinePayloadPayload)
		if !ok {
			return ctxerrors.Wrapf(commerr.ErrInvalidValue, "%s payload is %T", message.Name, message.Payload)
		}

		if err := handler.HandleTelemetryInlinePayload(ctx, payload); err != nil {
			return ctxerrors.Wrapf(err, "handle %s", message.Name)
		}

		return nil
	}

	return ctxerrors.Wrapf(asyncapirt.ErrUnknownMessage, "%s", message.Name)
}

// Client sends and receives this API's messages over a transport.
type Client struct {
	transport asyncapirt.Transport
}

// NewClient returns a client that uses transport.
func NewClient(transport asyncapirt.Transport) *Client {
	return &Client{transport: transport}
}

// Close closes the transport.
func (c *Client) Close() error {
	if err := c.transport.Close(); err != nil {
		return ctxerrors.Wrap(err, "close transport")
	}

	return nil
}

// SendCommand validates payload and sends it as a MessageCommand message.
// Send a command.
func (c *Client) SendCommand(ctx context.Context, payload Command) error {
	if err := asyncapirt.Send(ctx, c.transport, payload); err != nil {
		return ctxerrors.Wrapf(err, "send %s", MessageCommand)
	}

	return nil
}

// Run reads messages until ctx ends or the transport fails and passes each one
// to handler. Messages that match nothing go to HandleUnknownMessage. Run stops
// at the first error a handler returns.
func (c *Client) Run(ctx context.Context, handler Handler) error {
	logger := ctxscope.GetLogger(ctx)
	logger.Info("receive loop started")

	for {
		data, err := c.transport.ReadMessage(ctx)
		if err != nil {
			if ctx.Err() != nil {
				logger.Info("receive loop stopped", "reason", "context_done")

				return ctxerrors.Wrap(ctx.Err(), "receive loop")
			}

			return ctxerrors.Wrap(err, "read message")
		}

		message, err := DecodeReceivedMessage(data)
		if err != nil {
			if handleErr := handler.HandleUnknownMessage(ctx, data, err); handleErr != nil {
				return ctxerrors.Wrap(handleErr, "handle unknown message")
			}

			continue
		}

		if err := Dispatch(ctx, handler, message); err != nil {
			return ctxerrors.Wrap(err, "dispatch message")
		}
	}
}
